  yit = `Dämpning vid mjukt/fullt tryck på vänster avtryckare`,
  bit = `Avtryckardämpning är aktiverat för mjukt/fullt tryck på vänster avtryckare. Intryckning av avtryckaren inklusive klick dämpar musrörelser tills helt släppt.`,
  xit = `Dämpning vid mjukt/fullt tryck på båda avtryckarna`,
  Sit = `Avtryckardämpning är aktiverad för mjukt/fullt tryck på båda avtryckarna. Intryckning av avtryckaren inklusive klick dämpar musrörelser tills helt släppt.`,
  Cit = `Avtryckardämpningsmängd`,
  wit = `Detta ställer in hur mycket musrörelsen ska dämpas. Flytta till höger för att stoppa musrörelser.`,
  Tit = `Styrspakens minsta X-outputvärde`,
  Eit = `Detta värde avgör minsta mängd output som styrspaken skickar vid svep. Justera helst så att spelets inbyggda dödzon kompenseras exakt. Justera värdet uppåt tills långsamma rörelser varken stannar av eller blir hackiga, utan istället ger rena rörelser. Justera värdet nedåt om små rörelser känns för stora. Se även inställningen Förbättra små rörelser.`,
  Dit = `Styrspakens minsta Y-outputvärde`,
  Oit = `Detta värde avgör minsta mängd output som styrspaken skickar vid svep. Justera helst så att spelets inbyggda dödzon kompenseras exakt. Justera värdet uppåt tills långsamma rörelser varken stannar av eller blir hackiga, utan istället ger rena rörelser. Justera värdet nedåt om små rörelser känns för stora. Se även inställningen Förbättra små rörelser.`,
  kit = `Inputtyp: mus som styrspak`,
  Ait = `Den här inputtypen känns som en mus men matar ut en styrspak. Detta är avsett för spel som inte tillåter mus- och spelkontrollsinput på samma gång. Det är det näst bästa alternativet till en riktig mus och ger emulerad 1:1-respons. Obs! Eftersom detta läge ses av spelet som en styrspak, begränsas känslighetsresponsen av spelets känslighetsinställningar för spelkontroller. För bästa resultat, ställ in spelets kamerakänslighet för spelkontroller till högsta möjliga värde.`,
  jit = `Inputtyp: mus`,
  Mit = `Input översätter styrspak till mus- eller muspekaroutput. Obs: Input kan både påverkas av layoutens känslighet och muskänsligheten i spelet.`,
  Nit = `Gyroskop – outputskala`,
  Pit = `Används tillsammans med en platta i mus som styrspak-läget för att justera gyrots relativa input till att vara mindre eller större.`,
  Fit = `Gyroskopets känslighet`,
  Iit = `Använd kontrollpreferenser`,
  Lit = `Alla gyrolägen har gemensamma inställningar för känslighet, utjämning, acceleration och vinkelförskjutning. Om detta anges används inställningarna från kontrollens inställningar istället för de lägesspecifika inställningarna.`,
  Rit = `Gyro – gradkänslighet`,
  zit = `När punkter per 360° grader har kalibrerats korrekt i spelet multipliceras output från gyroskopet till musen. 1x ger 1:1 rotation av gyrot i verkligheten jämfört med rotation i världen. 2x roterar den globala kameran dubbelt så snabbt som handkontrollens rotation.`,
  Bit = `Gyro – gradkänslighet`,
  Vit = `När högsta vridningshastighet i spelet har kalibrerats korrekt multipliceras output från gyroskopet till musen. 1x ger 1:1 rotation av gyrot i verkligheten jämfört med rotation i spelet. 2x roterar den globala kameran dubbelt så snabbt som handkontrollens rotation.`,
  Hit = `Gyrolutningspunkt`,
  Uit = `Detta anger hur mycket kontrollen måste vridas för att aktivera lutkommandon.`,
  Wit = `Beteende för knapp`,
  Git = `Beteendet för gyroskopets inputknapp kan växlas. Om det är avstängt inaktiveras gyroskopet när man trycker på knappen.`,
  Kit = `Beteende för gyroknapp – På`,
  qit = `Med denna inställning aktiveras enhetens gyro när knappen trycks ned.`,
  Jit = `Beteende för gyroknapp – Av`,
  Yit = `Med denna inställning inaktiveras enhetens gyro när knappen trycks ned.`,
  Xit = `Beteende för gyroknapp – Växling`,
