  hat = `Använd haptik med hög intensitet.`,
  gat = `Yttre ringens kommandoradie`,
  _at = `När man är utanför denna radie, skickas den valda knappen eller tangenten. Till exempel kan ”spring”- eller ”sprinta”-knappen utlösas vid tryck av kanten. Skjutreglaget kan visualiseras som en förlängning av radien från mitten och utåt, med punkten där den yttre ringen börjar.`,
  vat = `Kommando för yttre ring`,
  yat = `När man är utanför denna radie, skickas den valda knappen eller tangenten. Till exempel kan ”spring”- eller ”sprinta”-knappen utlösas vid tryck av kanten.`,
  bat = `Invertera kommando för yttre ring`,
  xat = `Kommandot skickas när man är innanför radien för den yttre ringen. Till exempel kan ”gå” eller ”smyg” skickas när man är innanför ett visst område.`,
  Sat = `Invertering av yttre ring – På`,
  Cat = `Den valda knappen skickas när man är innanför den specificerade kommandoradien för den yttre ringen. Till exempel kan ”gå” eller ”smyg” skickas när man är innanför ett visst område.`,
  wat = `Invertering av yttre ring – Av`,
  Tat = `Den valda knappen skickas när man är utanför den specificerade kommandoradien för den yttre ringen. Till exempel kan ”spring” eller ”sprinta” skickas när man är utanför ett visst område.`,
  Eat = `Avtryckardämpning`,
  Dat = `Avtryckardämpning minskar mängden av rörelse som matas ut av detta läge medan avtryckaren trycks in.`,
